def solve(s, k):
    counts = {}
    for c in s:
        if c == 'B':
            counts['B'] += 1
    operations = []

    for i in range(len(s)):
        difference = len(s) - (counts['A'] * i)
        if difference >= k and difference <= counts.get('B', 0):
            count_b = counts['B'] - counts['A']
            count_a = counts['A']
            while count_a < k - count_b:
                operations.append((i + 1, 'A'))
                counts['A'] += 1
        if len(operations) == i + 1 and difference >= k - (counts['B'] * (len(s) // len(s[0]) - 1)):
            operation_c = 'B'
            count_b = counts['B'] - (i + 1)
            count_a = counts.get('A', 0)

            while count_a < k - count_b:
                operations.append((i + 2, operation_c))
                counts['A'] += 1
                count_a += i + 1
    return len(operations), '\n'.join(map(str, operations))

