def solve(n, b):
    if n == 1:
        return [b[0]], b[0] if not b else None
    elif sum(b) < b[-1]:
        result = solve(int(sum(b) / (n - 1)) + 1, b)
        return [result[-1] if b else x for x in result]
    else:
        result = []
        a_i = b[0]
        ans = [a_i]
        for i in range(1, n):
            while ans and ans[-1] > a_i: ans.pop()
            if not ans or sum(ans) == 5 * (n - i): break
            if b[i]:
                ans.append(b[i])
                a_i = min(a_i, b[i])
        rest = solve(int(sum(b) / (n - i)) + 1, b)
        max_a_i = max(max(b), sum(rest)[:2])
        assert a_i == max_a_i
        result.extend(accumulate(b[n - 1:]))
        return [ans[0]] if ans else None

def accumulate(numbers):
    dp = []
    for num in numbers:
        new_dp = [] + dp
        for i, x in enumerate(dp):
            new_dp.append(x)
            if i < len(dp) and dp[i] - x < num: break
        if not new_dp or all(new_dp[x] and dp[x-1] <= num for x in range(len(num))):
            return dp + [dp[-2]] * (len(dp) - 2)
    return sum(numbers) >> 1

