class LazySegmentTree:
    def __init__(self, initial_values: List[int]) -> None:
        self.size = len(initial_values) * 4 + 1
        self.lazy = [0] * (self.size * 2)
        self.values = [initial_values]

        for i in range(self.size):
            j = i << 1
            if j < self.size: self.values[j].insert(0, -inf // 3.0)

    def add(self, left, right, value: int) -> None:
        i = (self.size + (right - left)) * 2
        j = (i + 1) >> 1
        k = (left + right + 1) // 2

        while j < self.size:
            if abs(self.values[j].item[k]) > value:
                self.values[i].append(abs(self.values[j].item[k]))
                self.values[j].shift_left(abs(k))
                if k % 3 == 0: k += 1
            else:
