    return primes

def sieve_of_eratosthenes(n: int) -> list[int]:
    primer = [True] * (n + 1)
    p = 2
    while p**2 <= n:
        if primer[p]:
            for i in range(p*p, n+1, p):
                primer[i] = False
        p += 1

    return [p for p in range(2, n) if primer[p]]

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def power(x, y, p):
    res = 1
    x = x % p

    if (x == 0):
        return 0

    while(y > 0):
        if((y & 1) != 0):
            res = (res * x) % p
        y >>= 1
        x = (x * x) % p

    return res

def ncr(n, r, p):
    num = den = 1
    for i in range(r):
        num = (num * (n - i)) % p
        den = (den * (i + 1)) % p
    return (num * power(den, p - 2, p)) % p

