class LazySegTree(object):

    def __init__(self, data, op, e):
        """initialize the lazy seg tree with data"""
        _len = len(data)
        self._op = op
        self._e = e

        self._L = [_ for _ in data]
        self._R = [[] for _ in range(_len)]
        for i in range(_len):
            L, R = self._L[i], self._R[i]
            self._R[i] = [self._op(x, y) for x, y in zip(L, R)].append(e)

        self.n = _len
        self._mid = (_len - 1) >> 1

    def set(self, p, x):
        """set value at p in the segment tree"""
        if p < self._mid:
            self._L[p] += [x]
            for i in reversed(range(p)):
                self._R[i].append((self._op if i else IDENTITY, self._e))
        else:
            self._R[p - self._mid] += [(x, self._e)]

    def get(self, p):
        """get value at p in the segment tree"""
        if not p:

            return self._e
        p = p + self._mid
        ret, v = IDENTITY, None

        while p:

           v = (self._op if p <= self._mid else operator.add)\
              (
                  ret,
                  functools.reduce(
                      self._R[p - 1][1],
                      self._L[p] + self._R[p - 1][0],
                      DefaultDict(int, operator.add)()
                      )
                  )

           p >>= 1
        return v

    def fold(self, start, stop):
        l = self.get(start)
        r = self.get(stop - 1)

        if l == r:   
            return l            
        m = self._op(l, r)
        ret = defaultdict(int, {}
        def _fold(a, b):

            while True:
                if not a and not b:
                    return DefaultDict(int, m)
                if not a or not b:
                    break

                a = reduce(
                    lambda x,
                        functools.reduce(
                            operator.add,
                            self._R[x][0],
                            defaultdict(int, IDENTITY)()
                            )
                        , a + self._L[x], defaultdict(int, IDENTITY)())
                b = reduce(
                    lambda x,
                        functools.reduce(
                            operator.add,
                            self._R[x][1],
                            DefaultDict(int, IDENTITY)()
                            ),
                            self._R[x][-1],
                            defaultdict(int, IDENTITY)
                        )

                _fold(a[b], r[b])


            return a
        return _fold(l, r)

