  def solve(self, a: list[int], n: int):
    prefix = set()
    max_r = float('inf')

    for i in range(n):
        if len(prefix) == max_r:
            break
        suffix = set(a[i+1:])
        cur_set = set(a[:i+1])

        new_suff_len = len(suffix) - len(cur_set)
        new_set_len = len(prefix) - len(cur_set)

