def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left halves = merge_sort(arr[:mid])
    right halves = merge_sort(arr[mid:])
    merged = []
    while left halves and right halves:
        if left[-1] >= right[-1]:
            merged.append(left.pop())
        else:
            merged.append(right.pop())
    merged.extend(left)
    merged.extend(right)
    return merged

