class FastIO(IOBase):
    newlines = 0 

    def __init__(self, file):
        self._fd = file.fileno()
        self.buffer = BytesIO()
        self.writable = "x" in file.mode or "r" not in file.mode
        self.write = self.buffer.write if self.writable else None

    def read(self):
        while True:
            b = sys.stdin.read().decode("ascii")
            if not b:
                break

            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)


        self.newlines = 1 - self.buffer.seek(0, 2).count("\n") 

    def readline(self):
        while self.newlines == 1:
            b = sys.stdin.read().decode("ascii")
            self.newlines = b.count("\r\n") + (not b)
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)

    def flush(self):
        if self.writable:
            sys.stdin.flush()


