                elif j < len(v) and arr[j % n] == (i*1):
                    c4_digit = i
                    c3_digit_0 = v[i]
                    c2_digits_0 = v[(j//9)+1] + v [(j//9)+ 2*(10**((n-2)- j%36))]
                else:
                    continue

                p4_val = Decimal('9')
                if u[0]**3 < c4_digit <= getcontext().prec:
                    if ((n - j) % 4 == 1 or getcontext().prec >= 100):
                        p4_val -= Decimal(10**(i+2))

                for i_in_dp in range(c3_digit_0+1, c4_digit+1):
