from collections import deque

def solve(n: int, m: int):
    if n * m == 0:
        print(0)
        return

    queue = deque([
        {'x': 1, 'y': 1},
        {'x': 2, 'y': 2}
    ])

    dist = [[float('inf')] * (n + m) for _ in range(n + m)]
    min_cost = n * m

    while queue:
        curr_pos = queue.popleft()

        if curr_pos['x'] == 1 and curr_pos['y'] == 1: 
            min_cost = 0
            break

        neighbor = {}
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            x, y = curr_pos['x'] + dx, curr_pos['y'] + dy

            if 1 <= x <= n and 1 <= y <= m: 
                if dist[x][y] == float('inf'):
                    neighbor[{'x': x, 'y': y}]= {'x': math.floor(x / 2), 'y': math.ceil(y / 2)}

        for k, v in neighbor.items():
            if not (k['x'], k['y']) in [d['x', d['y']] for d in dist]:
                # calculate cost to reach the new position
                curr_cost = dist[curr_pos['x',curr_pos['y']]] + math.sqrt( 2 * ((v['x'] - curr_pos['x']))**2 + (v['y'] - curr_pos['y'])**2)

                if curr_cost < dist[k['x'], k['y]]:
                    dist[k['x'], k['y']] = curr_cost
                    queue.append(k)

    print(min_cost)

