def binary_search(nums, target):
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid + 1 if nums[: mid].count(target) > 0 else mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

